using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.Domination.TotalDominationFormulas;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.Domination;

internal sealed class TotalDominationBlowupDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/Domination/TotalDominationBlowup.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Independent fibres retain actual total-domination subsets and give the known polynomial substitution.",
        H("Independent-fibre substitution on actual subsets"), Blocks(
            Paragraph(Text("V and W are actual finite vertex types, with Fintype instances. G is an arbitrary SimpleGraph on V. For the total-domination identity W is nonempty. Each v is replaced by the independent fibre consisting of all (v,i) with i in W. Vertices in two fibres are adjacent exactly when their original vertices are adjacent. An occupied fibre contributes a nonempty actual subset, not one selected representative.")),
            Node("blowupGraph", "The actual independent-fibre graph", All("V",Type,All("G",Graph(V("V")),All("W",Type,All("a",ProdType(V("V"),V("W")),All("b",ProdType(V("V"),V("W")),IffTo(Adj(Call("blowupGraph",V("G"),V("W")),V("a"),V("b")),Adj(V("G"),Call("fst",V("a")),Call("fst",V("b")))))))),
                "The result has vertex type V times W and adjacency G.Adj(a.fst,b.fst). There are no internal edges in a fibre. This is SimpleGraph.comap Prod.fst, so symmetry and looplessness are inherited. It is the edgeless-fibre lexicographic blowup, not a clique blowup.", DescribeRole.Definition),
            Node("subsetFamilyEquiv", "Actual subset-to-fibre equivalence", BothTypes(And(All("S",Set(ProdType(V("V"),V("W"))),All("v",V("V"),All("i",V("W"),IffTo(Member(V("i"),Call("subsetFamilyEquiv",V("S"),V("v"))),Member(Par(Seq(V("v"),Comma,V("i"))),V("S")))))),All("f",Seq(V("V"),To,Sp,Set(V("W"))),All("v",V("V"),All("i",V("W"),IffTo(Member(Par(Seq(V("v"),Comma,V("i"))),Call("symm",Call("subsetFamilyEquiv"),V("f"))),Member(V("i"),Call("f",V("v")))))))),true),
                "For finite V and W this is an equivalence between Finset(V times W) and V -> Finset W. A global subset S maps at v to all i in W with (v,i) in S. The inverse maps f to all (v,i) with i in f(v). Extensional membership proves the inverse laws. The private cardinal theorem says the inverse subset cardinality equals sum_v card(f(v)).", DescribeRole.Definition),
            Node("support", "Occupied fibres", BothTypes(All("f",Seq(V("V"),To,Sp,Set(V("W"))),All("v",V("V"),IffTo(Member(V("v"),Call("support",V("f"))),Call("Nonempty",Call("f",V("v")))))),true),
                "support(f) is the finite subset of all v in V for which f(v) is nonempty. For nonempty W, the private total_family theorem proves that the actual inverse subset totally dominates blowupGraph G W if and only if this support totally dominates G. The forward direction tests any vertex in each fibre; the reverse direction uses a selected neighbour in an occupied adjacent fibre. Selected vertices obey exactly the same condition.", DescribeRole.Definition),
            Node("blowup_polynomial", "The known actual-subset substitution identity", BothTypes(Inst(Call("Nonempty",V("W")),All("G",Graph(V("V")),Eq(Poly(Call("blowupGraph",V("G"),V("W"))),Call("comp",Poly(V("G")),Sub(Pow(Add(D(1),Cast(V("X"),PolynomialType(Complex))),Call("card",V("W"))),D(1)))))),true),
                "For every finite V,W, nonempty W, and SimpleGraph G on V, T_blowup(x)=T_G((1+x)^card(W)-1) in C[X]. Both polynomials are the literal subset sums defined in TotalDominationSeeds.complexPolynomial. The fibre equivalence, cardinal sum and occupied-support equivalence reduce the left side to a sum over families. For a fixed support A, product-of-sums and the sum of all nonempty fibre subsets give ((1+x)^card(W)-1)^card(A). Summing the supports gives polynomial composition. The displayed independent-fibre formula is proved here from actual subsets. It is retained as a mathematical ingredient, with no assertion of original discovery. No attribution to an unread H-join theorem is used.", DescribeRole.Theorem),
            Node("labelled_root_blowup", "A common labelled pullback for every actual root", All("n",Nat,All("G",Graph(Fin(V("n"))),Imp(Leq(D(2),V("n")),Imp(NoIso(V("G"),Fin(V("n"))),All("eta",Complex,Imp(Root(Poly(V("G")),V("eta")),All("k",Nat,Imp(Lt(D(0),V("k")),Some("m",Nat,Some("H",Graph(Fin(V("m"))),And(Leq(D(2),V("m")),Ne(Poly(V("H")),D(0)),NoIso(V("H"),Fin(V("m"))),All("w",Complex,Imp(Eq(Pow(Add(D(1),V("w")),V("k")),Add(D(1),V("eta"))),Root(Poly(V("H")),V("w"))))))))))))))),
                "For every n>=2, actual graph G : SimpleGraph (Fin n) without isolates, complex root eta of complexPolynomial G, and positive natural k, there exist m>=2 and an actual isolate-free H : SimpleGraph (Fin m) with nonzero complexPolynomial H. Every complex w satisfying (1+w)^k=1+eta is a root of that same H. The graph is the independent-fibre blowup of G by Fin k, reindexed once to Fin m. Its leading coefficient is one; thus no nonzero assumption on the seed is needed beyond the actual no-isolate graph. This generalizes the live seed pullback to the negative family without a conditional density premise.", DescribeRole.Theorem),
            Paragraph(Text("The independent-fibre identity supplies the common pullback used in the complex approximation argument. It differs from clique substitution because a selected vertex has no neighbour inside its own fibre."))), []));

    private static DocumentBlock Node(string selector, string title, Formula formula, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("td-blowup-" + selector.Replace("_", "-").ToLowerInvariant()), DeclarationHandle.Create(Prefix + selector),
            H(title), StatementSource.FromAuthor(Disp(formula)), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
}
